253	/// пять»): декодирование бинлога, применение к книге — один проход по
254	/// файлам и кадрам, тем же кодом, что файловый `verify` (`Reader` читает
255	/// кадры, `FileReplayer` группирует их в обновления, `Book` их применяет);
256	/// `LevelTracker` на каждую конфигурацию развешивает уровни и трейды
257	/// независимо, кормится одними и теми же кадрами (`feed_frames_multi`).
258	/// Разрыв последовательности (`Err` из `apply`) останавливает файл для всех
259	/// конфигураций разом, как в `verify`: дальше этот файл недоверен,
260	/// следующий идёт с чистого листа. Возвращает `ReplayStats` в том же
261	/// порядке, что `cfgs`.
262	pub(crate) fn replay_symbol_over_configs(
263	    root: &Path,
264	    symbol: &str,
265	    cfgs: &[LevelsConfig],
266	) -> anyhow::Result<Vec<ReplayStats>> {
267	    replay_symbol_over_configs_keep(root, symbol, cfgs, ReplayKeep::ALL)
268	}
269	
270	/// То же, но с выбором, что хранить (`ReplayKeep`); `replay_symbol_over_configs`
271	/// — частный случай `ALL`.
272	pub(crate) fn replay_symbol_over_configs_keep(
273	    root: &Path,
274	    symbol: &str,
275	    cfgs: &[LevelsConfig],
276	    keep: ReplayKeep,
277	) -> anyhow::Result<Vec<ReplayStats>> {
278	    anyhow::ensure!(
279	        !cfgs.is_empty(),
280	        "replay_symbol_over_configs: пустая сетка конфигураций"
281	    );
282	    let prefix = format!("{symbol}-");
283	    let files = list_symbol_binlogs(root, symbol)?;
284	    if files.is_empty() {
285	        // Таск 19, критерий 4: каталог старого формата (до таска 19 `lob
286	        // session` писала `<SYMBOL>.binlog` без даты) не должен молча
287	        // выглядеть как «нет суточных файлов» — владелец переименовывает
288	        // руками, но узнать об этом обязан из сообщения, не из тишины.
289	        // Архивный суффикс (T46) проверяется так же, как обычный.
290	        for suffix in [
291	            crate::binlog::BINLOG_SUFFIX,
292	            crate::binlog::BINLOG_ARCHIVE_SUFFIX,
293	        ] {
294	            let name = format!("{symbol}{suffix}");
295	            let undated = root.join(&name);
296	            if undated.is_file() {
297	                anyhow::bail!(
298	                    "файл `{name}` без даты — запись старого формата, переименуйте в \
299	                     `{symbol}-<дата>{suffix}` ({} в {})",
300	                    undated.display(),
301	                    root.display()
302	                );
303	            }
304	        }
305	        anyhow::bail!("нет суточных файлов {prefix}*.binlog в {}", root.display());
306	    }
307	    // Счётчики GC (байт/записей) — по одному экземпляру на конфигурацию,
308	    // хотя декодирование общее: значения совпадут у всех, но `+=` читает
309	    // поле, а не только пишет его (та же идиома, что у `replay_symbol` до
310	    // этого таска — единственная актуальная альтернатива читать поле
311	    // разом после цикла тем же способом, каким это уже делает `ReplayStats
312	    // .days` ниже).
313	    let mut out: Vec<ReplayStats> = cfgs
314	        .iter()
315	        .map(|_| ReplayStats {
316	            days: Vec::new(),
317	            bytes: 0,
318	            records: 0,
319	            tick_e9: 0,
320	            step_e9: 0,
321	            open: Vec::new(),
322	        })
323	        .collect();
324	    let mut work: Vec<DayWork> = Vec::new();
325	    for path in &files {
326	        let name = path
327	            .file_name()
328	            .map(|s| s.to_string_lossy().into_owned())
329	            .unwrap_or_default();
330	        let day = day_of_filename(&prefix, &name)
331	            .ok_or_else(|| anyhow::anyhow!("имя {name} не разбирается как сутки"))?;
332	        let data = std::fs::read(path)
333	            .map_err(|e| anyhow::anyhow!("файл {} не читается: {e}", path.display()))?;
334	        for s in &mut out {
335	            s.bytes += data.len() as u64;
336	        }
337	        let mut reader = Reader::open(&data[..])
338	            .map_err(|e| anyhow::anyhow!("заголовок {}: {e:?}", path.display()))?;
339	        let header = reader.header();
340	        for s in &mut out {
341	            s.tick_e9 = header.tick_e9;
342	            s.step_e9 = header.step_e9;
343	        }
344	        if work.last().is_none_or(|w| w.day != day) {
345	            let trackers: Vec<LevelTracker> = match work.last() {
346	                Some(prev) if keep.carry_age && is_next_day(&prev.day, &day) => prev
347	                    .trackers
348	                    .iter()
349	                    .zip(cfgs)
350	                    .map(|(t, &cfg)| LevelTracker::with_carried_births(cfg, t.live_births()))
351	                    .collect(),
352	                _ => cfgs.iter().map(|&cfg| LevelTracker::new(cfg)).collect(),
353	            };
354	            work.push(DayWork {
355	                day,
356	                records: cfgs.iter().map(|_| Vec::new()).collect(),
357	                touches: cfgs.iter().map(|_| Vec::new()).collect(),
358	                approaches: cfgs.iter().map(|_| Vec::new()).collect(),
359	                mids: Vec::new(),
360	                trackers,
361	            });
362	        }
363	        let entry = work
364	            .last_mut()
365	            .ok_or_else(|| anyhow::anyhow!("рабочий день только что добавлен, а его нет"))?;
366	        let mut book = Book::new(header.tick_e9, header.step_e9);
367	        let mut replayer = FileReplayer::new();
368	        let mut ups = Vec::new();
369	        let mut tps = Vec::new();
370	        let mut file_ok = true;
371	        loop {
372	            let frame = super::parts::read_frame_soft(&mut reader, path)?;
373	            let Some(frame_records) = frame else { break };
374	            for s in &mut out {
375	                s.records += frame_records.len() as u64;
376	            }
377	            for rec in &frame_records {
378	                ups.clear();
379	                tps.clear();
380	                replayer.push_frame(
381	                    std::slice::from_ref(rec),
382	                    header.tick_e9,
383	                    header.step_e9,
384	                    &mut ups,
385	                    &mut tps,
386	                );
387	                let hit = trade_hit_from_record(rec);
388	                debug_assert_eq!(
389	                    tps.len(),
390	                    usize::from(hit.is_some()),
391	                    "разметка сделок обязана совпадать с FileReplayer"
392	                );
393	                for up in &ups {
394	                    if book.apply(up).is_err() {
395	                        file_ok = false;
396	                        break;
397	                    }
398	                    feed_frames_multi(
399	                        &book,
400	                        &mut entry.trackers,
401	                        up.cts_ms,
402	                        &mut entry.records,
403	                        &mut entry.touches,
404	                        &mut entry.approaches,
405	                        &mut entry.mids,
406	                    );
407	                    entry.trim(keep);
408	                }
409	                if !file_ok {
410	                    break;
411	                }
412	                if let Some(h) = hit {
413	                    for tracker in &mut entry.trackers {
414	                        tracker.observe_trade(h);
415	                    }
416	                }
417	            }
418	            if !file_ok {
419	                break;
420	            }
421	        }
422	        if file_ok {
423	            let mut tail = Vec::new();
424	            replayer.finish(&mut tail);
425	            for up in &tail {
426	                if book.apply(up).is_err() {
427	                    break;
428	                }
429	                feed_frames_multi(
430	                    &book,
431	                    &mut entry.trackers,
432	                    up.cts_ms,
433	                    &mut entry.records,
