    pub fn verify_at_seq(
        &self,
        snap: &OrderbookSnapshot,
        tick_e9: i64,
        step_e9: i64,
    ) -> Result<SnapshotDiff, AlignmentError> {
        if self.book.last_seq() != Some(snap.seq) {
