/// `verify-<SYMBOL>.status == ok` в корне (В-56): `touches`, `backtest`,
/// `bounce-grid` — как `touch-profiles`. `allow` снимает требование только
/// для отладочных данных; такой прогон в `runs.csv` не идёт.
pub(crate) fn require_verified(
    root: &std::path::Path,
    symbol: &str,
    allow: bool,
) -> anyhow::Result<()> {
    if allow {
        return Ok(());
    }
    let marker = root.join(format!("verify-{symbol}.status"));
    anyhow::ensure!(
        profiles::read_verify_marker(&marker),
        "{}: маркер сверки не `ok` — сутки не проверены (fail-closed, В-56; К1 аудита 18.09);          для отладочных данных — --allow-unverified",
        marker.display()
    );
    Ok(())
}

/// Пишет `bytes` во временный файл и переименовывает поверх `path` — читатель
/// живого каталога никогда не видит полуфайл (`session.json`, `dashboard`'s
/// `data.json`/`coin-<SYMBOL>.json`). Общий помощник вместо двух копий
/// (ревью 23.09, W7): `session.rs` и `dashboard.rs` держали один и тот же
/// приём порознь. `tmp_path` — параметром, не выводится из `path` здесь:
/// у `session.json` он `session.json.tmp` (дописанное расширение), у файлов
/// дашборда — `path.with_extension("tmp")` (заменённое); унификация имени
/// временного файла не входит в этот ремонт, только сама запись+переименование.
pub(crate) fn write_atomic(
    path: &std::path::Path,
    tmp_path: &std::path::Path,
    bytes: &[u8],
) -> anyhow::Result<()> {
    std::fs::write(tmp_path, bytes)
        .map_err(|e| anyhow::anyhow!("не записать {}: {e}", tmp_path.display()))?;
    std::fs::rename(tmp_path, path).map_err(|e| {
        anyhow::anyhow!(
            "не переименовать {} → {}: {e}",
            tmp_path.display(),
            path.display()
        )
    })
}

