1	//! Формы сделки-отскока: выход (`ExitForm`, F7), одна форма сетки
2	//! (`GridForm`) и построение сетки `stops × takes × DEADLINE_SECS` с осями
3	//! срока жизни входа, формы входа, формы выхода и «прилипания»
4	//! (`grid_forms*`). Вынесено из `bounce_grid` при разрезке B3 (ревью
5	//! 23.09), поведение не менялось.
6	
7	use crate::commands::lob::backtest::{BounceForm, EntryForm, EntryTtl, StopForm, TakeForm};
8	use crate::commands::lob::bounce_verdict::form_label_with_entry;
9	
10	/// Форма выхода (F7 этапа F, Б-75): как закрывать позицию.
11	#[derive(Debug, Clone, Copy, PartialEq)]
12	pub enum ExitForm {
13	    /// `none` — как сейчас (стоп/тейк/дедлайн/трейл/съедание от максимума).
14	    None,
15	    /// `eat<X>` — стена съедена сделками: накопленные сделки в стену ≥ X % от
16	    /// размера стены на входе. Выход по рынку всего остатка.
17	    Eat { pct: f64 },
18	    /// `gone<W>` — стена снята без сделок: размер упал ниже (1 − W %) от
19	    /// размера на входе, И съедение сделками < половины падения.
20	    Gone { pct: f64 },
21	    /// `gone<W>tr<T>` — то же снятие, но позиция не закрывается сразу: взводится трейл,
22	    /// выход — откат на `T` % (от входа) от лучшей цены после снятия (владелец 2026-09-23:
23	    /// «сразу выход по снятию — глупость, но снятие — это уже риск, нужна защита»).
24	    GoneTrail { pct: f64, trail_pct: f64 },
25	    /// `gone<W>be` / `gone<W>bex` — снятие переносит стоп в безубыток (мягко: когда позиция у
26	    /// безубытка; жёстко: позиция хуже безубытка закрывается сразу), дальше базовый трейл плана
27	    /// (владелец 2026-09-23: «снятие — стоп в ноль, дальше базовый трейлинг»).
28	    GoneBe { pct: f64, hard: bool },
29	}
30	
31	impl ExitForm {
32	    /// Имя формы несёт число ровно тем, чем считали (`eat33.7`, не `eat34`) —
33	    /// как `pct{x}`/`tk{x}` у стопа и тейка: имя в `forms.csv`/`runs.csv` и
34	    /// порог предрегистрации обязаны совпадать (ревью 21.09).
35	    pub fn label(&self) -> String {
36	        match self {
37	            ExitForm::None => "none".to_string(),
38	            ExitForm::Eat { pct } => format!("eat{pct}"),
39	            ExitForm::Gone { pct } => format!("gone{pct}"),
40	            ExitForm::GoneTrail { pct, trail_pct } => format!("gone{pct}tr{trail_pct}"),
41	            ExitForm::GoneBe { pct, hard } => {
42	                format!("gone{pct}be{}", if *hard { "x" } else { "" })
43	            }
44	        }
45	    }
46	
47	    pub fn parse(spec: &str) -> anyhow::Result<Self> {
48	        if spec == "none" {
49	            return Ok(ExitForm::None);
50	        }
51	        if let Some(rest) = spec.strip_prefix("eat") {
52	            let pct: f64 = rest.parse()?;
53	            anyhow::ensure!(
54	                pct.is_finite() && pct > 0.0 && pct <= 100.0,
55	                "eat<X>: X ∈ (0, 100]"
56	            );
57	            return Ok(ExitForm::Eat { pct });
58	        }
59	        if let Some(rest) = spec.strip_prefix("gone") {
60	            if let Some((w, mode)) = rest.split_once("be") {
61	                let pct: f64 = w.parse()?;
62	                anyhow::ensure!(
63	                    pct.is_finite() && pct > 0.0 && pct <= 100.0,
64	                    "gone<W>be: W ∈ (0, 100]"
65	                );
66	                let hard = match mode {
67	                    "" => false,
68	                    "x" => true,
69	                    _ => anyhow::bail!("--exit-form {spec:?}: ожидается gone<W>be или gone<W>bex"),
70	                };
71	                let form = ExitForm::GoneBe { pct, hard };
72	                anyhow::ensure!(
73	                    form.label() == spec,
74	                    "--exit-form {spec:?}: имя не каноническое (ожидалось {})",
75	                    form.label()
76	                );
77	                return Ok(form);
78	            }
79	            if let Some((w, t)) = rest.split_once("tr") {
80	                let pct: f64 = w.parse()?;
81	                let trail_pct: f64 = t.parse()?;
82	                anyhow::ensure!(
83	                    pct.is_finite() && pct > 0.0 && pct <= 100.0,
84	                    "gone<W>tr<T>: W ∈ (0, 100]"
85	                );
86	                anyhow::ensure!(
87	                    trail_pct.is_finite() && trail_pct > 0.0 && trail_pct < 100.0,
88	                    "gone<W>tr<T>: откат T — % от входа в (0, 100)"
89	                );
90	                let form = ExitForm::GoneTrail { pct, trail_pct };
91	                anyhow::ensure!(
92	                    form.label() == spec,
93	                    "--exit-form {spec:?}: имя не каноническое (ожидалось {})",
94	                    form.label()
95	                );
96	                return Ok(form);
97	            }
98	            let pct: f64 = rest.parse()?;
99	            anyhow::ensure!(
100	                pct.is_finite() && pct > 0.0 && pct <= 100.0,
101	                "gone<W>: W ∈ (0, 100]"
102	            );
103	            return Ok(ExitForm::Gone { pct });
104	        }
105	        anyhow::bail!("--exit-form {spec:?}: ожидается none | eat<X> | gone<W>");
106	    }
107	}
108	
109	/// Одна форма сетки (В-65): имя колонки, форма сделки, дедлайн (он же окно `σ`),
110	/// режим срока жизни входа (F5, В-74), форма входа (F6, В-73) и форма выхода (F7, Б-75).
111	#[derive(Debug, Clone, Copy, PartialEq)]
112	pub struct GridForm {
113	    pub label: &'static str,
114	    pub form: BounceForm,
115	    pub deadline_secs: i64,
116	    /// Режим срока жизни входа (F5, В-74): `touch` — прежний, секунды/`wall` —
117	    /// условия рынка плюс потолок. Имя формы у нетронутого режима не меняется
118	    /// (`form_label`), у остальных несёт суффикс `-ttl<значение>` — имена
119	    /// обязаны различаться, иначе `run_bounce_grid` отказывает на повторе.
120	    pub entry_ttl: EntryTtl,
121	    /// Форма входа (F6, В-73): `single@fr` — прежнее имя формы без поля входа
122	    /// (гейт «те же круги»), лестница — поле `<вход>` первым в имени.
123	    pub entry_form: EntryForm,
124	    /// Форма выхода (F7, Б-75): `none` (прежнее поведение), `eat<X>` или `gone<W>`.
125	    pub exit_form: ExitForm,
126	    /// Выход по «прилипанию» (B4, В-58 п. 5; ось сетки — аудит дизайна 22.09 §6 п. 2, В-85):
127	    /// `None` — выключен (прежнее поведение и имена), `Some(x)` — через `x` с после входа
128	    /// уровень всё ещё лучшая цена → выход по рынку (`ExitReason::Early`). Значения — только из
129	    /// предрегистрированного набора В-58 (`EARLY_EXITS_S`).
130	    pub early_exit_secs: Option<i64>,
131	}
132	
133	/// Формы сетки в порядке `stops × takes × DEADLINE_SECS`; имена —
134	/// `bounce_verdict::form_label`, их же читает вердикт. Повторы имён отвергает
135	/// `run_bounce_grid`. Это — прежний режим входа (F5, В-74): `touch`,
136	/// прежняя форма выхода (F7, Б-75): `none`.
137	pub fn grid_forms(
138	    stops: &[StopForm],
139	    takes: &[TakeForm],
140	    take_floor_fees: Option<f64>,
141	    deadlines: &[u64],
142	) -> Vec<GridForm> {
143	    grid_forms_with_entry_ttl(
144	        stops,
145	        takes,
146	        take_floor_fees,
147	        deadlines,
148	        &[EntryTtl::Touch],
149	        &[ExitForm::None],
150	    )
151	}
152	
153	/// Та же сетка, но с осями срока жизни входа (F5, В-74) и формы выхода
154	/// (F7, Б-75): значения `entry_ttl`/`exit_form` — **внутренние** множители,
155	/// поэтому при `&[EntryTtl::Touch]` и `&[ExitForm::None]` порядок
156	/// и имена форм те же, что у `grid_forms` (гейт «те же круги»).
157	pub fn grid_forms_with_entry_ttl(
158	    stops: &[StopForm],
159	    takes: &[TakeForm],
160	    take_floor_fees: Option<f64>,
161	    deadlines: &[u64],
162	    ttls: &[EntryTtl],
163	    exits: &[ExitForm],
164	) -> Vec<GridForm> {
165	    grid_forms_with_axes(
166	        stops,
167	        takes,
168	        take_floor_fees,
169	        deadlines,
170	        ttls,
171	        &[EntryForm::SingleFrontrun],
172	        exits,
173	    )
174	}
175	
176	/// Полная сетка F7 (Б-75): к осям F6 добавлена ось **формы выхода**
177	/// (`--exit-form`, повторяемый). Форма выхода — самый внешний множитель, поэтому
178	/// при `&[ExitForm::None]` порядок и имена форм те же, что у
179	/// `grid_forms_with_axes` (гейт «те же круги»): у `none` поле выхода в
180	/// имени не пишется (`form_label_with_entry`).
181	pub fn grid_forms_with_axes(
182	    stops: &[StopForm],
183	    takes: &[TakeForm],
184	    take_floor_fees: Option<f64>,
185	    deadlines: &[u64],
186	    ttls: &[EntryTtl],
187	    entries: &[EntryForm],
188	    exits: &[ExitForm],
189	) -> Vec<GridForm> {
190	    let mut out = Vec::with_capacity(
191	        exits.len() * entries.len() * stops.len() * takes.len() * deadlines.len() * ttls.len(),
192	    );
193	    for &exit_form in exits {
194	        for &entry_form in entries {
195	            for &stop in stops {
196	                for &take in takes {
197	                    for &deadline in deadlines {
198	                        let base = form_label_with_entry(
199	                            &entry_form.label(),
200	                            &stop.label(),
201	                            &take.label(),
202	                            deadline,
203	                        );
204	                        for &entry_ttl in ttls {
205	                            let label_with_ttl: &'static str = match entry_ttl {
206	                                // Прежний режим — прежнее имя: вердикт и «золото» F3/F4
207	                                // читают `form_label` как есть.
208	                                EntryTtl::Touch => Box::leak(base.clone().into_boxed_str()),
209	                                other => Box::leak(
210	                                    format!("{base}-ttl{}", other.label()).into_boxed_str(),
211	                                ),
212	                            };
213	                            let label = if matches!(exit_form, ExitForm::None) {
214	                                label_with_ttl
215	                            } else {
216	                                Box::leak(
217	                                    format!("{label_with_ttl}-{}", exit_form.label())
218	                                        .into_boxed_str(),
219	                                )
220	                            };
221	                            out.push(GridForm {
222	                                label,
223	                                form: BounceForm {
224	                                    stop,
225	                                    take,
226	                                    take_floor_fees,
227	                                },
228	                                deadline_secs: deadline as i64,
229	                                entry_ttl,
230	                                entry_form,
231	                                exit_form,
232	                                early_exit_secs: None,
233	                            });
234	                        }
235	                    }
236	                }
237	            }
238	        }
239	    }
240	    out
241	}
242	
243	/// Ось выхода по «прилипанию» (аудит дизайна 22.09, В-85) поверх полной сетки F7 — самый
244	/// внешний множитель: при `&[None]` порядок и имена форм те же, что у `grid_forms_with_axes`
245	/// (гейт «те же круги»); включённое значение добавляет к имени хвост `-early<x>`.
246	#[allow(clippy::too_many_arguments)]
247	pub fn grid_forms_with_early(
248	    stops: &[StopForm],
249	    takes: &[TakeForm],
250	    take_floor_fees: Option<f64>,
251	    deadlines: &[u64],
252	    ttls: &[EntryTtl],
253	    entries: &[EntryForm],
254	    exits: &[ExitForm],
255	    earlies: &[Option<i64>],
256	) -> Vec<GridForm> {
257	    let base = grid_forms_with_axes(
258	        stops,
259	        takes,
260	        take_floor_fees,
261	        deadlines,
262	        ttls,
263	        entries,
264	        exits,
265	    );
266	    let mut out = Vec::with_capacity(base.len() * earlies.len());
267	    for &early in earlies {
268	        for f in &base {
269	            let mut g = *f;
270	            if let Some(x) = early {
271	                g.label = Box::leak(format!("{}-early{x}", f.label).into_boxed_str());
272	                g.early_exit_secs = Some(x);
273	            }
274	            out.push(g);
275	        }
276	    }
277	    out
278	}
