15	/// Форма стопа сделки-отскока — **база из файлов «отскок»** (E6, В-64/В-65)
16	/// плюс σ (В-62) для сравнения. Позиционные формы считаются от цены уровня
17	/// `P` и цены входа (первый фронтранер, иначе `P ± 1` тик). Форма, которую
18	/// для касания построить нельзя (нет фронтрана, нет второй плотности завала,
19	/// нет `σ`, стоп совпал бы со входом или лёг по ту же сторону), сигнала не
20	/// даёт — `bounce_plan` возвращает `None`, вызывающий считает пропуск.
21	#[derive(Debug, Clone, Copy, PartialEq)]
22	pub enum StopForm {
23	    /// Перед плотностью: `P + 1` тик для бида — «остопиться в плотность, а
24	    /// лучше перед ней за один тик» [D 12:56], «стоп я кидал перед этой
25	    /// крупной заявкой» [S 31:26]. Нужен вход от фронтрана дальше тика.
26	    Before,
27	    /// В плотность: `P` [D 12:56].
28	    At,
29	    /// За плотностью: `P − 1` (форма T38; у практиков — только «мёртвая
30	    /// монета» [D 12:20]).
31	    Behind,
32	    /// Середина фронтрана: посередине между входом и `P` (пять положений
33	    /// стопа, [K 18:00]); нужен фронтран дальше двух тиков.
34	    MidFrontrun,
35	    /// За второй плотностью завала: тик за `stack_next_tick` — «стоп за
36	    /// первую-вторую плотность» [D 13:41]; нужна вторая плотность в окне.
37	    BehindStack,
38	    /// Процент от входа: «от фронтрана до стопа 0,5–2 %» [D 06:33].
39	    Pct(f64),
40	    /// `a × σ_H` bps от входа, не ближе тика за плотностью (В-62, наша форма).
41	    Sigma(f64),
42	}
43	
44	impl StopForm {
45	    /// Имя формы в сетке и в `runs.csv`: `before|at|behind|midfr|stack2|pct<x>|s<a>`.
46	    pub fn label(self) -> String {
47	        match self {
48	            Self::Before => "before".to_string(),
49	            Self::At => "at".to_string(),
50	            Self::Behind => "behind".to_string(),
51	            Self::MidFrontrun => "midfr".to_string(),
52	            Self::BehindStack => "stack2".to_string(),
53	            Self::Pct(x) => format!("pct{x}"),
54	            Self::Sigma(a) => format!("s{a}"),
55	        }
56	    }
57	
58	    /// Разбор имени; неканоническое (`s1.0`, `pct01`) — отказ.
59	    pub fn parse(label: &str) -> anyhow::Result<Self> {
60	        let form = match label {
61	            "before" => Self::Before,
62	            "at" => Self::At,
63	            "behind" => Self::Behind,
64	            "midfr" => Self::MidFrontrun,
65	            "stack2" => Self::BehindStack,
66	            _ => {
67	                if let Some(rest) = label.strip_prefix("pct") {
68	                    Self::Pct(parse_mult(rest, label)?)
69	                } else if let Some(rest) = label.strip_prefix('s') {
70	                    Self::Sigma(parse_mult(rest, label)?)
71	                } else {
72	                    anyhow::bail!(
73	                        "{label}: форма стопа не из базы (before|at|behind|midfr|stack2|pct<x>|s<a>)"
74	                    )
75	                }
76	            }
77	        };
78	        anyhow::ensure!(
79	            form.label() == label,
80	            "{label}: имя формы стопа не каноническое (ожидалось {})",
81	            form.label()
82	        );
83	        form.validate()?;
84	        Ok(form)
85	    }
86	
87	    fn validate(self) -> anyhow::Result<()> {
88	        match self {
89	            Self::Pct(x) => anyhow::ensure!(
90	                x.is_finite() && x > 0.0 && x < 100.0,
91	                "pct{x}: процент стопа обязан быть в (0, 100)"
92	            ),
93	            Self::Sigma(a) => anyhow::ensure!(
94	                a.is_finite() && a >= 0.0,
95	                "s{a}: множитель σ стопа — конечное число ≥ 0"
96	            ),
97	            _ => {}
98	        }
99	        Ok(())
100	    }
101	}
102	
103	/// Форма тейка: `1:1` от входа — единственная общая у практиков [D 16:17]
104	/// («тейк частями» — E7, после стопов), `b × σ_H` (В-62) или **трейл**
105	/// (владелец 19.09: «что трейла нет — это плохо»): активируется при ходе
106	/// `activate_pct` % от входа в плюс, дальше тянется на `trail_pct` % от лучшей
107	/// цены; фиксированного тейка у трейла нет (`strategy`: при `trail_bps > 0`
108	/// тейк-лимит не работает).
109	#[derive(Debug, Clone, Copy, PartialEq)]
110	pub enum TakeForm {
111	    OneToOne,
112	    /// Тейк в процентах **от входа**, независимо от стопа (S8 плана по
113	    /// сторонам, 20.09): у лонгов от старых стен 83 выхода из 89 — по часу,
114	    /// тейк 1:1 при стопе 2 % недостижим; `tk0.5` — +0.5 % от входа в
115	    /// сторону отскока.
116	    Pct(f64),
117	    Sigma(f64),
118	    Trail {
119	        activate_pct: f64,
120	        trail_pct: f64,
121	    },
122	    /// E7 «частями» (Z 1:07:37 «половина на середине хода»): половина
123	    /// позиции лимитом на 1:1, остаток — до стопа, дедлайна, трейла (если
124	    /// задан флагами) или съедания; второй раз на 1:1 не закрывается.
125	    HalfOneToOne,
126	    /// E5/E7 по чужим ботам (`density-bots-2026-09-19.md`, их дефолты
127	    /// 50/80): тейк 1:1 целиком, плюс выход по съеданию плотности от
128	    /// максимума с входа — `half_pct` % → половина по рынку, `all_pct` % →
129	    /// весь остаток по рынку. Имя `eat<half>x<all>`.
130	    Eaten {
131	        half_pct: f64,
132	        all_pct: f64,
133	    },
134	}
135	
136	impl TakeForm {
137	    /// Имя: `1to1`, `t<b>` или `tr<активация>x<откат>` в процентах (`tr0.5x0.3`).
138	    pub fn label(self) -> String {
139	        match self {
140	            Self::OneToOne => "1to1".to_string(),
141	            Self::Pct(x) => format!("tk{x}"),
142	            Self::Sigma(b) => format!("t{b}"),
143	            Self::Trail {
144	                activate_pct,
145	                trail_pct,
146	            } => format!("tr{activate_pct}x{trail_pct}"),
147	            Self::HalfOneToOne => "half1to1".to_string(),
148	            Self::Eaten { half_pct, all_pct } => format!("eat{half_pct}x{all_pct}"),
149	        }
150	    }
151	
152	    pub fn parse(label: &str) -> anyhow::Result<Self> {
153	        let form = if label == "1to1" {
154	            Self::OneToOne
155	        } else if label == "half1to1" {
156	            Self::HalfOneToOne
157	        } else if let Some(rest) = label.strip_prefix("eat") {
158	            let (h, a) = rest
159	                .split_once('x')
160	                .ok_or_else(|| anyhow::anyhow!("{label}: съедание — eat<половина %>x<всё %>"))?;
161	            let half_pct = parse_mult(h, label)?;
162	            let all_pct = parse_mult(a, label)?;
163	            anyhow::ensure!(
164	                half_pct.is_finite()
165	                    && all_pct.is_finite()
166	                    && half_pct > 0.0
167	                    && half_pct < all_pct
168	                    && all_pct <= 100.0,
169	                "{label}: пороги съедания — 0 < половина < всё ≤ 100 %"
170	            );
171	            Self::Eaten { half_pct, all_pct }
172	        } else if let Some(rest) = label.strip_prefix("tk") {
173	            let x = parse_mult(rest, label)?;
174	            anyhow::ensure!(
175	                x.is_finite() && x > 0.0 && x < 100.0,
176	                "{label}: процент тейка обязан быть в (0, 100)"
177	            );
178	            Self::Pct(x)
179	        } else if let Some(rest) = label.strip_prefix("tr") {
180	            let (a, t) = rest
181	                .split_once('x')
182	                .ok_or_else(|| anyhow::anyhow!("{label}: трейл — tr<активация>x<откат>"))?;
183	            let activate_pct = parse_mult(a, label)?;
184	            let trail_pct = parse_mult(t, label)?;
185	            anyhow::ensure!(
186	                activate_pct.is_finite()
187	                    && activate_pct > 0.0
188	                    && trail_pct.is_finite()
189	                    && trail_pct > 0.0,
190	                "{label}: активация и откат трейла — конечные числа > 0"
191	            );
192	            Self::Trail {
193	                activate_pct,
194	                trail_pct,
195	            }
196	        } else if let Some(rest) = label.strip_prefix('t') {
197	            Self::Sigma(parse_mult(rest, label)?)
198	        } else {
199	            anyhow::bail!(
200	                "{label}: форма тейка не из базы (1to1|tk<x>|half1to1|eat<h>x<a>|t<b>|tr<a>x<t>)"
201	            )
202	        };
203	        anyhow::ensure!(
204	            form.label() == label,
205	            "{label}: имя формы тейка не каноническое (ожидалось {})",
206	            form.label()
207	        );
208	        if let Self::Sigma(b) = form {
209	            anyhow::ensure!(
210	                b.is_finite() && b >= 0.0,
211	                "t{b}: множитель σ тейка — конечное число ≥ 0"
212	            );
213	        }
214	        Ok(form)
215	    }
216	}
217	
218	fn parse_mult(rest: &str, label: &str) -> anyhow::Result<f64> {
219	    rest.parse::<f64>()
220	        .map_err(|_| anyhow::anyhow!("{label}: число после префикса не разобралось"))
221	}
