223	/// Форма сделки одной структурой: стоп, тейк и пол σ-тейка в кругах комиссий
224	/// (`take_floor_fees × ROUNDTRIP_FEES_BPS`; у `1to1` пола нет — как в файлах).
225	#[derive(Debug, Clone, Copy, PartialEq)]
226	pub struct BounceForm {
227	    pub stop: StopForm,
228	    pub take: TakeForm,
229	    pub take_floor_fees: Option<f64>,
230	}
231	
232	impl BounceForm {
233	    /// Сборка из имён CLI с проверкой: σ-тейк требует пол, пол — число > 0.
234	    pub fn parse(stop: &str, take: &str, take_floor_fees: Option<f64>) -> anyhow::Result<Self> {
235	        let form = Self {
236	            stop: StopForm::parse(stop)?,
237	            take: TakeForm::parse(take)?,
238	            take_floor_fees,
239	        };
240	        form.validate()?;
241	        Ok(form)
242	    }
243	
244	    pub fn validate(self) -> anyhow::Result<()> {
245	        self.stop.validate()?;
246	        if let TakeForm::Sigma(b) = self.take {
247	            anyhow::ensure!(
248	                b.is_finite() && b >= 0.0,
249	                "t{b}: множитель σ тейка — конечное число ≥ 0"
250	            );
251	        }
252	        if let Some(k) = self.take_floor_fees {
253	            anyhow::ensure!(
254	                k.is_finite() && k > 0.0,
255	                "--take-floor-fees {k}: пол тейка — конечное число > 0 кругов комиссий"
256	            );
257	        }
258	        if matches!(self.take, TakeForm::Sigma(_)) {
259	            anyhow::ensure!(
260	                self.take_floor_fees.is_some(),
261	                "тейк {} требует --take-floor-fees (пол в кругах комиссий, В-62)",
262	                self.take.label()
263	            );
264	        }
265	        Ok(())
266	    }
267	
268	    /// Нужна ли форме `σ_H` касания.
269	    pub fn needs_sigma(self) -> bool {
270	        matches!(self.stop, StopForm::Sigma(_)) || matches!(self.take, TakeForm::Sigma(_))
271	    }
272	}
273	
274	/// Расстояние в bps от цены `entry_tick` (в тиках) — в целых тиках, не
275	/// меньше одного: `ceil(bps / 10⁴ × entry_tick)`. Округление вверх — чтобы
276	/// расстояние было **не меньше** заданного (стоп не ближе `a × σ`, тейк не
277	/// ниже `b × σ`), а цена всегда стояла на сетке тиков.
278	#[allow(clippy::cast_precision_loss, clippy::cast_possible_truncation)]
279	pub(super) fn bps_to_ticks_ceil(bps: f64, entry_tick: i64) -> i64 {
280	    let ticks = (bps / 10_000.0 * entry_tick as f64).ceil();
281	    (ticks as i64).max(1)
282	}
283	
284	/// Имя прежнего входа (F6): одиночная нога у фронтранера касания, иначе
285	/// `P ± 1` тик. Трёхпольные имена форм (`<стоп>-<тейк>-<H>`, В-65) читаются как
286	/// `single@fr-…`, а сетка с этой формой входа пишет **прежнее** трёхпольное
287	/// имя — на нём стоит гейт «те же круги» (F3/F4/F5).
288	pub const SINGLE_ENTRY_LABEL: &str = "single@fr";
289	
290	/// Форма входа (F6 этапа F, В-73): нога у фронтранера или **лестница** от
291	/// `from` до `to` bps над стеной (для аска — под). Числа `N`, `from`, `to`, `w`
292	/// задаёт предрегистрация **именем формы**; умолчаний в коде нет.
293	#[derive(Debug, Clone, Copy, PartialEq)]
294	pub enum EntryForm {
295	    /// `single@fr` — прежний вход: цена фронтранера касания, иначе `P ± 1`
296	    /// тик (T38, В-65). Гейт «те же круги».
297	    SingleFrontrun,
298	    /// `ladder<N>x<from>..<to>[w<k>]` — `N` ног от `from` до `to` bps над
299	    /// стеной равными долями (`$ / N`), либо **вес к стене** `k`: нижняя
300	    /// (ближайшая к стене) нога весит `k` долей — цитата практика «основной
301	    /// объём к сайзу» [T 1:31:42].
302	    Ladder {
303	        legs: u8,
304	        from_bps: f64,
305	        to_bps: f64,
306	        wall_weight: u32,
307	    },
308	}
309	
310	impl EntryForm {
311	    /// Разбор имени формы. Каноничность проверяется как у `StopForm`/
312	    /// `TakeForm`: `ladder03x02..10` или `…w1` — не имя, а другая запись того
313	    /// же (и «попробовать ещё одно» здесь было бы лишним испытанием).
314	    pub fn parse(spec: &str) -> anyhow::Result<Self> {
315	        let spec = spec.trim();
316	        if spec == SINGLE_ENTRY_LABEL {
317	            return Ok(Self::SingleFrontrun);
318	        }
319	        let rest = spec.strip_prefix("ladder").ok_or_else(|| {
320	            anyhow::anyhow!(
321	                "{spec}: форма входа — {SINGLE_ENTRY_LABEL} или ladder<N>x<from>..<to>[w<k>]"
322	            )
323	        })?;
324	        let (legs_s, tail) = rest
325	            .split_once('x')
326	            .ok_or_else(|| anyhow::anyhow!("{spec}: лестница — ladder<N>x<from>..<to>[w<k>]"))?;
327	        let legs: u8 = legs_s
328	            .parse()
329	            .map_err(|_| anyhow::anyhow!("{spec}: число ног {legs_s:?} не разобралось"))?;
330	        anyhow::ensure!(
331	            (2..=MAX_ENTRY_LEGS as u8).contains(&legs),
332	            "{spec}: ног {legs}, а сетка имён — от 2 до {MAX_ENTRY_LEGS}"
333	        );
334	        let (range, weight_s) = match tail.split_once('w') {
335	            Some((r, w)) => (r, Some(w)),
336	            None => (tail, None),
337	        };
338	        let wall_weight: u32 = match weight_s {
339	            Some(w) => w
340	                .parse()
341	                .map_err(|_| anyhow::anyhow!("{spec}: вес {w:?} не разобрался"))?,
342	            None => 1,
343	        };
344	        anyhow::ensure!(
345	            wall_weight >= 1,
346	            "{spec}: вес к стене — целое ≥ 1 (1 — равные доли)"
347	        );
348	        let (from_s, to_s) = range
349	            .split_once("..")
350	            .ok_or_else(|| anyhow::anyhow!("{spec}: полоса лестницы — <from>..<to> bps"))?;
351	        let from_bps: f64 = from_s
352	            .parse()
353	            .map_err(|_| anyhow::anyhow!("{spec}: from {from_s:?} не число"))?;
354	        let to_bps: f64 = to_s
355	            .parse()
356	            .map_err(|_| anyhow::anyhow!("{spec}: to {to_s:?} не число"))?;
357	        anyhow::ensure!(
358	            from_bps.is_finite() && to_bps.is_finite() && from_bps > 0.0 && to_bps > from_bps,
359	            "{spec}: полоса лестницы — конечные 0 < from < to bps"
360	        );
361	        let form = Self::Ladder {
362	            legs,
363	            from_bps,
364	            to_bps,
365	            wall_weight,
366	        };
367	        anyhow::ensure!(
368	            form.label() == spec,
369	            "{spec}: имя формы входа не каноническое (ожидалось {})",
370	            form.label()
371	        );
372	        Ok(form)
373	    }
374	
375	    /// Имя формы: `single@fr` или `ladder3x2..10` / `ladder3x2..10w2`. Вес 1
376	    /// не пишется: равные доли — то же самое, а имя обязано быть одно.
377	    pub fn label(self) -> String {
378	        match self {
379	            Self::SingleFrontrun => SINGLE_ENTRY_LABEL.to_string(),
380	            Self::Ladder {
381	                legs,
382	                from_bps,
383	                to_bps,
384	                wall_weight,
385	            } => {
386	                let base = format!("ladder{legs}x{}..{}", fmt_bps(from_bps), fmt_bps(to_bps));
387	                if wall_weight > 1 {
388	                    format!("{base}w{wall_weight}")
389	                } else {
390	                    base
391	                }
392	            }
393	        }
394	    }
395	}
