397	/// Число bps в имени формы — как печатает `f64::to_string` (кратчайшая запись,
398	/// читаемая обратно тем же числом): `2`, `0.5`, `10`.
399	fn fmt_bps(v: f64) -> String {
400	    format!("{v}")
