403	/// Ноги лестницы формы (F6, В-73): `N` цен от `from` до `to` bps **над
404	/// стеной** (для аска — под, `away` = −1), каждая — целым числом тиков по
405	/// `bps_to_ticks_ceil` (расстояние не меньше заданного, цена на сетке тиков).
406	/// Совпавшие тики складываются в одну ногу с суммарной долей: биржа не
407	/// различает две заявки по одной цене, а доля — то, что видит позиция. Доли —
408	/// `$/N`, либо нижняя (ближайшая к стене) нога весит `wall_weight` долей.
409	///
410	/// Второе значение — средняя цена входа в тиках (по долям): от неё
411	/// `bounce_plan` считает стоп и тейк формы, как для одиночного входа от цены
412	/// фронтранера.
413	#[allow(clippy::cast_precision_loss)]
414	pub(super) fn ladder_legs(
415	    p_tick: i64,
416	    away: i64,
417	    legs: u8,
418	    from_bps: f64,
419	    to_bps: f64,
420	    wall_weight: u32,
421	) -> (EntryLadder, i64) {
422	    let n = usize::from(legs.max(2));
423	    let mut out = EntryLadder::NONE;
424	    // Доли: нижняя нога — `wall_weight`, остальные — по единице; сумма долей
425	    // нормируется на единицу.
426	    let total = wall_weight as f64 + (n - 1) as f64;
427	    let mut prev_tick: Option<i64> = None;
428	    for i in 0..n {
429	        let bps = from_bps + (to_bps - from_bps) * i as f64 / (n - 1) as f64;
430	        let tick = p_tick + away * bps_to_ticks_ceil(bps, p_tick);
431	        let frac = if i == 0 {
432	            wall_weight as f64 / total
433	        } else {
434	            1.0 / total
435	        };
436	        // Тики монотонны по `i` (`bps_to_ticks_ceil` не убывает), поэтому
437	        // совпавшие идут подряд: складываем долю в предыдущую ногу.
438	        if prev_tick == Some(tick) {
439	            let last = usize::from(out.n - 1);
440	            out.frac[last] += frac;
441	        } else {
442	            assert!(out.push(tick, frac), "ног не больше MAX_ENTRY_LEGS");
443	            prev_tick = Some(tick);
444	        }
445	    }
446	    // Средняя цена входа в тиках — ближайший тик к взвешенной сумме: цены
447	    // живут на сетке тиков (так же округляет `level_shift` стратегии).
448	    let avg = out.weighted_avg_tick().round() as i64;
449	    (out, avg)
450	}
