531	                    ENTRY_TTL_SECS.contains(&secs),
532	                    "--entry-ttl-secs {secs}: не из сетки замера В-74 {ENTRY_TTL_SECS:?}"
533	                );
534	                Ok(Self::Secs(secs))
535	            }
536	        }
537	    }
