539	    /// Имя значения для шапки артефакта и имени формы.
540	    pub fn label(self) -> String {
541	        match self {
542	            Self::Touch => "touch".to_string(),
543	            Self::Wall => "wall".to_string(),
544	            Self::Secs(s) => s.to_string(),
