546	    }
547	
548	    /// Порядок форм в сетке: `touch`, `wall`, затем секунды по возрастанию —
549	    /// тот же приём детерминированного порядка, что у дедлайнов.
550	    pub(crate) fn sort_key(self) -> (u8, i64) {
551	        match self {
552	            Self::Touch => (0, 0),
553	            Self::Wall => (1, 0),
554	            Self::Secs(s) => (2, s),
555	        }
556	    }
557	}
