125	/// События суток крейта из всех частей дня — в `Vec` **точного** размера:
126	/// сначала части считаются (`count_feed_events`), потом декодируются в
127	/// буфер с готовой ёмкостью. Рост удвоением держал старый и новый буфер
128	/// вместе (пик до 3× итога) и ронял сетку на сервере по OOM на сутках в
129	/// ~20 млн событий (2026-09-18); второй декод дешевле памяти.
130	pub(super) fn day_events(parts: &[PathBuf]) -> anyhow::Result<Vec<HbtEvent>> {
131	    let started = Instant::now();
132	    let mut total = 0usize;
133	    let mut counted_parts = 0usize;
134	    for path in parts {
135	        total += match cached_event_count(path) {
136	            Some(n) => n,
137	            None => {
138	                let mut feed = open_replay_feed(path)?;
139	                let n = count_feed_events(&mut feed);
140	                store_event_count(path, n);
141	                counted_parts += 1;
142	                n
143	            }
144	        };
145	    }
146	    let counted = started.elapsed().as_secs_f64();
147	    let mut events: Vec<HbtEvent> = Vec::with_capacity(total);
148	    for path in parts {
149	        let mut feed = open_replay_feed(path)?;
150	        feed_events_into(&mut feed, &mut events);
151	    }
152	    // Кэш числа событий — только ёмкость буфера: разошёлся — буфер просто
153	    // вырос, круги те же; сайдкары переписываются честным пересчётом.
154	    if events.len() != total {
155	        eprintln!(
156	            "bounce-grid:   события: кэш числа врал ({total} против {}), сайдкары пересчитаны",
157	            events.len()
158	        );
159	        for path in parts {
160	            let mut feed = open_replay_feed(path)?;
161	            let n = count_feed_events(&mut feed);
162	            store_event_count(path, n);
163	        }
164	    }
165	    eprintln!(
166	        "bounce-grid:   события: счёт {counted:.2}s ({counted_parts} из {} частей считано, остальные из кэша) · декод {:.2}s · {}",
167	        parts.len(),
168	        started.elapsed().as_secs_f64() - counted,
169	        events.len()
170	    );
171	    Ok(events)
172	}
