288	/// Готовые результаты форм уходят в `sink` **по порядку форм**: форма,
289	/// закончившая раньше соседей с меньшим индексом, ждёт в буфере (не больше
290	/// числа потоков), чтобы дамп не зависел от числа потоков.
291	struct FormOrder<'a> {
292	    pending: BTreeMap<usize, (BounceRun, Vec<BounceSignal>, u64)>,
293	    next_form: usize,
294	    done: usize,
295	    sink: &'a mut (dyn FnMut(FormDayResult, &[BounceSignal]) -> anyhow::Result<()> + Send),
296	}
