298	/// Все формы над одними сутками: потоки берут формы по счётчику. `Setups`
299	/// — один проход книги на сутки (`SignalWindows`, общий для форм), дальше у
300	/// каждой формы движок только внутри кругов; `Full` — у каждой формы свой
301	/// `Backtest` над всеми событиями суток (эталон гейта).
302	///
303	/// Память (сервер, 2026-09-18): сигналы формы строятся **в потоке, когда
304	/// форма взята** (например, 48 форм × 100 тыс. касаний × 128 Б заранее — 600 МБ), а
305	/// результат формы отдаётся `sink` сразу и до конца суток не копится
306	/// (`FormOrder`). Возвращает число форм, отданных в `sink`.
307	///
308	/// `approaches` — записи подхода (F6, `--signal approach`): те же сутки и тот
309	/// же порядок, что `touches` (их вид как касания); `None` — сигнал по касаниям.
310	pub(super) fn drive_day(
311	    events: &[HbtEvent],
312	    windows: Option<&SignalWindows>,
313	    touches: &[TouchRecord],
314	    approaches: Option<&[crate::lob::levels::ApproachRecord]>,
315	    forms: &[GridForm],
316	    p: DayParams<'_>,
317	    sink: &mut (dyn FnMut(FormDayResult, &[BounceSignal]) -> anyhow::Result<()> + Send),
318	) -> anyhow::Result<usize> {
319	    let next = AtomicUsize::new(0);
320	    let failure: Mutex<Option<anyhow::Error>> = Mutex::new(None);
321	    let order = Mutex::new(FormOrder {
322	        pending: BTreeMap::new(),
323	        next_form: 0,
324	        done: 0,
325	        sink,
326	    });
327	    std::thread::scope(|scope| {
328	        for _ in 0..p.threads.max(1) {
329	            scope.spawn(|| loop {
330	                let i = next.fetch_add(1, Ordering::Relaxed);
331	                if i >= forms.len() {
332	                    break;
333	                }
334	                if failure.lock().map(|f| f.is_some()).unwrap_or(true) {
335	                    break;
336	                }
337	                let cfg = DriveConfig {
338	                    // R2: размер несёт каждый сигнал (`BounceSignal::qty`,
339	                    // `signals_for`); размер прогона сетке не нужен.
340	                    order_qty: 0.0,
341	                    first_order_id: 1,
342	                    queue_model: p.queue_model,
343	                };
344	                let step = signals_for(touches, approaches, p.sigma, &forms[i], &p).and_then(
345	                    |(signals, skipped)| {
346	                        let driven = match windows {
347	                            Some(w) => match p.memos {
348	                                // Память формы берёт один поток за раз: форма в наборе одна.
349	                                Some(ms) => {
350	                                    let mut m = ms[i]
351	                                        .lock()
352	                                        .unwrap_or_else(std::sync::PoisonError::into_inner);
353	                                    drive_bounce_windowed_memo(
354	                                        events, w, &signals, &cfg, p.rtt_ns, &mut m,
355	                                    )
356	                                }
357	                                None => drive_bounce_windowed(events, w, &signals, &cfg, p.rtt_ns),
358	                            },
359	                            None => with_backtest_over(
360	                                events,
361	                                p.tick,
362	                                p.lot,
363	                                p.rtt_ns,
364	                                p.queue_model,
365	                                |bt| drive_bounce(bt, 0, &signals, &cfg),
366	                            ),
367	                        };
368	                        driven
369	                            .map(|run| (run, signals, skipped))
370	                            .map_err(|e| anyhow::anyhow!("форма #{i}: {e}"))
371	                    },
372	                );
373	                let flushed = match step {
374	                    Ok((run, signals, skipped)) => match order.lock() {
375	                        Ok(mut o) => {
376	                            o.pending.insert(i, (run, signals, skipped));
377	                            let mut res = Ok(());
378	                            loop {
379	                                let form = o.next_form;
380	                                let Some((run, signals, skipped)) = o.pending.remove(&form) else {
381	                                    break;
382	                                };
383	                                res = (o.sink)(FormDayResult { form, run, skipped }, &signals);
384	                                o.next_form += 1;
385	                                o.done += 1;
386	                                if res.is_err() {
387	                                    break;
388	                                }
389	                            }
390	                            res
391	                        }
392	                        Err(_) => Err(anyhow::anyhow!("результаты форм: мьютекс")),
393	                    },
394	                    Err(e) => Err(e),
395	                };
396	                if let Err(e) = flushed {
397	                    if let Ok(mut f) = failure.lock() {
398	                        if f.is_none() {
399	                            *f = Some(e);
400	                        }
401	                    }
402	                    break;
403	                }
404	            });
405	        }
406	    });
407	    if let Some(e) = failure.into_inner().ok().flatten() {
408	        return Err(e);
409	    }
410	    let o = order
411	        .into_inner()
412	        .map_err(|_| anyhow::anyhow!("результаты форм: мьютекс"))?;
413	    anyhow::ensure!(
414	        o.pending.is_empty(),
415	        "формы без записи в дамп: {}",
416	        o.pending.len()
417	    );
418	    Ok(o.done)
419	}
