421	/// Окна сетапов суток (`--driver setups`): снимок книги на каждый `t0`
422	/// касания — один раз на сутки, общий для всех форм **и наборов** (`--set`):
423	/// касания те же, фильтры наборов только выбирают из них сигналы.
424	pub(super) fn day_windows(
425	    events: &[HbtEvent],
426	    touches: &[TouchRecord],
427	    driver: DriverArg,
428	    tick: f64,
429	    lot: f64,
430	) -> Option<SignalWindows> {
431	    match driver {
432	        DriverArg::Full => None,
433	        DriverArg::Setups => {
434	            let t0s: Vec<i64> = touches
435	                .iter()
436	                .map(|t| t.start_ms.saturating_mul(1_000_000))
437	                .collect();
438	            let started = Instant::now();
439	            let w = SignalWindows::build(events, &t0s, tick, lot);
440	            eprintln!(
441	                "bounce-grid:   окна: снимков {} · уровней всего {} (в среднем {:.0} на снимок) · {:.2}s",
442	                w.len(),
443	                w.levels_total(),
444	                w.levels_total() as f64 / w.len().max(1) as f64,
445	                started.elapsed().as_secs_f64()
446	            );
447	            Some(w)
448	        }
449	    }
450	}
