396	    pub(crate) fn admits(&self, ti: usize, t: &TouchRecord) -> bool {
397	        if self.frontrun_only && t.frontrun_tick.is_none() {
398	            return false;
399	        }

400	        // База E1 (В-66): плотность обязана держать порог при подходе цены,
401	        // а не только при рождении — иначе в сетку идут касания
402	        // «бывших» плотностей. Окно проверено при старте прогона.
403	        if self.mode.holds_at_touch(t) != Some(true) {
404	            return false;
405	        }
406	        if self.min_age_ms.is_some_and(|n| t.age_ms() < n) {
407	            return false;
408	        }
409	        if let Some(s_min) = self.min_flow_pct {
410	            let flow_ok = t.flow_1h_lots > 0
411	                && t.size_at_touch as f64 / t.flow_1h_lots as f64 * 100.0 >= s_min;
412	            if !flow_ok {
413	                return false;
414	            }
415	        }
416	        // Ось стороны: другая сторона выбывает до форм (как возраст и сила).
417	        if self.side.is_some_and(|s| t.side != s) {
418	            return false;
419	        }
420	        // Состояние стены: съедена к касанию сильнее порога — не вход.
421	        if self.eaten_max_pct.is_some_and(|m| eaten_pct(t) > m) {
422	            return false;
423	        }
424	        // Размер стены: номинал при касании ниже порога набора — не вход.
425	        if self.usd_min.is_some_and(|m| {
426	            t.price_tick as f64 * self.tick * t.size_at_touch as f64 * self.lot < m
427	        }) {
428	            return false;
429	        }
430	        // Контекст (S4): ход до касания и режим — вне границ набора или
431	        // без значения при заданной границе — не вход.
432	        if let Some(ctx) = self.ctx {
433	            let c = &ctx[ti];
434	            if !self
435	                .ctx_ranges
436	                .iter()
437	                .zip(&c.axes)
438	                .all(|(r, v)| r.holds(*v))
439	            {
440	                return false;
441	            }
442	        }
443	        true
444	    }

