            // (`first_id .. first_id + legs`) не должен разъехаться с тем,
            // что ноги нет: они уже пропускают отсутствующий в учёте
            // крейта id, как и здесь.
            if leg_qtys[j] <= 0.0 {
                continue;
            }
            leg_qtys[j]
        } else if ladder.n > 0 {
