                    order_id,
                    px_i,
                    qty_i,
                    entry_tif,
                    OrdType::Limit,
                    entry_wait,
                )?;
            }
        }
    }
    state.phase = Phase::EntryPending {
        order_id: first_id,
        sent_ns: now,
        legs,
    };
